// DSHA_TOOL_FINISH_IDENTITY_RC2_V1: preserve valid structure, render malformed calls as non-executable diagnostics.
const assembledBlocks = live.blocks();
const invalidIdentity = assembledBlocks.some(block => block.type === "tool-call" && !(typeof block.id === "string" && block.id.trim() !== "" && typeof block.name === "string" && block.name.trim() !== ""));
const message = createAssistantMessage({
	content: assembledBlocks.map(block => block.type === "tool-call" && !(typeof block.id === "string" && block.id.trim() !== "" && typeof block.name === "string" && block.name.trim() !== "") ? { type: "text", text: "[DSHA_INVALID_TOOL_CALL] Missing tool name/id in this step. No tool in this step was executed; no automatic replay." } : block),

// DSHA_TOOL_FINISH_IDENTITY_V2: dispatch nothing; the step's ToolCallRecovery closes valid calls as not started.
if (invalidIdentity) throw new LlmError("DSHA_INVALID_TOOL_CALL: missing name/id; this step was not dispatched. No automatic replay.", "INVALID_RESPONSE");
if (finish.kind === "max-tokens") return { kind: "max-tokens" };
